app.component("modalEliminarComponent",{template:'\n    <style>\n       \n        .modal-confirm  .modal-confirm-content  {\n            padding: 20px;\n            border-radius: 5px;\n            border: none;\n            text-align: center;\n            font-size: 14px;\n        }\n        .modal-confirm .modal-header {\n            border-bottom: none;   \n            position: relative;\n        }\n        .modal-confirm h5 {\n            text-align: center;\n            font-size: 26px;\n            margin: 30px 0 -10px;\n        }\n        .modal-confirm .close {\n            position: absolute;\n            top: -5px;\n            right: -2px;\n        }\n       \n        .modal-confirm .modal-footer {\n            border: none;\n            text-align: center;\t\t\n            border-radius: 5px;\n            font-size: 13px;\n            padding: 10px 15px 25px;\n        }\n        .modal-confirm .modal-footer a {\n            color: #999;\n        }\t\t\n        .modal-confirm .icon-box {\n            width: 80px;\n            height: 80px;\n            margin: 0 auto;\n            border-radius: 50%;\n            z-index: 9;\n            text-align: center;\n            border: 3px solid #f15e5e;\n        }\n        .modal-confirm .icon-box i {\n            color: #f15e5e;\n            font-size: 46px;\n            display: inline-block;\n            margin-top: 13px;\n        } \n        .modal-confirm .btn-danger {\n            background: #f15e5e;\n        }\n        .modal-confirm .btn-danger:hover, .modal-confirm .btn-danger:focus {\n            background: #ee3535;\n        }\n        .trigger-btn {\n            display: inline-block;\n            margin: 100px auto;\n        }\n    </style>\n    <div class="modal-confirm">\n        <div class="modal-confirm-content">\n            <div class="modal-header flex-column">\n                <div class="icon-box"> \n                    <i class="fa fa-times"></i>\n                </div>\t\t\t\t\t\t\n                <h5 class="modal-title w-100">¿Esta seguro que desea anular este documento?</h5>\t\n                <button type="button" class="close " data-dismiss="modal" aria-hidden="true"  ng-click="$ctrl.cancel()">&times;</button>\n            </div>\n            <div class="modal-body">\n                <p>Acceda a la página del SRI -> Facturación Electrónica -> Producción -> Anulación -> Solicitud de Anulación para anular el documento y evitar su validez tributaria. Esta acción es solo para control del sistema.</p>\n                <tabla-info-adicional-component data="dataObservaciones"></tabla-info-adicional-component>\n            </div>\n            <div class="modal-footer justify-content-center">\n            <button type="button" class="   btn btn-danger" ng-click="anular()">Si, anular!</button>\n                <button type="button" class="  btn btn-secondary" data-dismiss="modal" ng-click="$ctrl.cancel()">Cancelar</button>\n            </div>\n        </div>\n    </div>\n    ',bindings:{id:"=",resolve:"<",close:"&",dismiss:"&"},controller:["$scope","facturaService","formulario","toastService",function(n,o,a,e){n.dataObservaciones=[{nombre:"Motivo de anulación",valor:null}];const t=this;console.log(t);let i=0;t.$onInit=function(){i=t.resolve.params.id},n.anular=function(){i>0?0!==n.dataObservaciones.length?n.dataObservaciones.some(n=>!a.isValidField(n.nombre)||!a.isValidField(n.valor))?e.toastr({type:"warning",message:"Ingrese todos los campos"}):o.anular(i,n.dataObservaciones).then(n=>{"0"===n.code&&a.sweetAlert("warning",n.message),"1"===n.code&&(a.sweetAlert("success",n.message,1e3),t.close({esAnulado:!0}))}):e.toastr({type:"warning",message:"Ingrese motivo de anulación"}):e.toastr({type:"warning",message:"Id documento invalido"})},t.cancel=function(){t.dismiss()}}]});